function handAngle(hour: number, minutes: number): number {
  const minuteHand = 6 * minutes;
  const hourHand = 30 * (hour % 12) + 0.5 * minutes;
  const d = Math.abs(hourHand - minuteHand);
  return Math.min(d, 360 - d);
}

